libsrc = '''"""Shared grid helpers for ARC-style tasks."""

def compress(grid):
    """The grid without its frontiers: every row and every column that is one color throughout."""
    rows = {i for i, row in enumerate(grid) if len(set(row)) == 1}
    cols = {j for j in range(len(grid[0])) if len({row[j] for row in grid}) == 1}
    return [[v for j, v in enumerate(row) if j not in cols] for i, row in enumerate(grid) if i not in rows]

def split_by_frontier(grid):
    """Split the grid into the two regions on either side of a full one-color row or column frontier; returns (region1, region2, 'h'|'v')."""
    h, w = len(grid), len(grid[0])
    for i, row in enumerate(grid):
        if len(set(row)) == 1 and 0 < i < h - 1:
            return grid[:i], grid[i + 1:], 'h'
    for j in range(w):
        if len({row[j] for row in grid}) == 1 and 0 < j < w - 1:
            return [r[:j] for r in grid], [r[j + 1:] for r in grid], 'v'
    return None, None, None

def shared_color(region1, region2):
    """The one color present in both regions."""
    return ({v for r in region1 for v in r} & {v for r in region2 for v in r}).pop()

def compare_regions(region1, region2, marker):
    """Cellwise comparison: marker where both regions agree, otherwise their shared color."""
    s = shared_color(region1, region2)
    return [[marker if x == y else s for x, y in zip(ra, rb)] for ra, rb in zip(region1, region2)]
'''
